await addressBookReady;

const events = Glean.mail.accountHubLoaded.testGetValue();
Assert.deepEqual(
  events.map(v => v.extra.view_name),
  ["ADDRESS_BOOK", "localAddressBookSubview"]
);

Assert.equal(
  tabmail.currentTabInfo.mode.type,
  "addressBookTab",
  "Should have navigated to address book"
);

const index = booksList.getIndexForUID(addressBookDirectory.UID);
await TestUtils.waitForCondition(
  () => booksList.selectedIndex == index,
  `Waiting for the correct address book at index ${index} to be selected`
);

Assert.equal(
  tabmail.currentTabInfo.browser.contentDocument.activeElement.id,
  "searchInput",
  "Search input should have focus"
);

tabmail.closeOtherTabs(0);

MailServices.ab.deleteAddressBook(addressBookDirectory.URI);
